<script setup>
import {ref,computed,onMounted,watch,nextTick} from 'vue';import {withBase} from 'vitepress';import catalog from '../../../../data/catalog.json';
const all=ref([]),query=ref(''),region=ref(''),school=ref(''),tag=ref(''),page=ref(1),selected=ref([]),showCompare=ref(false),error=ref(''),loading=ref(true),note=ref('');const compareEl=ref(null);
const categories=['量化金融','金融与金融科技','统计与应用数学','数据与商业分析','经济与计量','管理与运筹','精算与风险管理'];
async function load(){loading.value=true;error.value='';try{const r=await fetch(withBase('/data/programs.json'));if(!r.ok)throw Error();all.value=await r.json();const params=new URLSearchParams(location.search);query.value=params.get('q')||'';selected.value=(params.get('compare')||'').split(',').filter(id=>all.value.some(p=>p.id===id)).slice(0,4);if(!selected.value.length){try{selected.value=JSON.parse(localStorage.getItem('grad-compare')||'[]').filter(id=>all.value.some(p=>p.id===id)).slice(0,4)}catch{}}const add=params.get('add');if(add&&all.value.some(p=>p.id===add)&&!selected.value.includes(add)){if(selected.value.length<4)selected.value=[...selected.value,add];else note.value='已选满 4 个项目，请先移除一个再加入。';}if(params.has('compare')&&selected.value.length)showCompare.value=true;}catch{error.value='项目数据加载失败，请检查网络后重试。'}finally{loading.value=false;}}
onMounted(load);
const schools=computed(()=>catalog.schools.filter(s=>!region.value||s.region===region.value));
watch(region,()=>{school.value=''});watch([query,region,school,tag],()=>{page.value=1});
watch(selected,v=>{try{localStorage.setItem('grad-compare',JSON.stringify(v))}catch{}},{deep:true});
const filtered=computed(()=>all.value.filter(p=>(!region.value||p.region===region.value)&&(!school.value||p.schoolId===school.value)&&(!tag.value||p.tags.includes(tag.value))&&query.value.toLowerCase().split(/\s+/).filter(Boolean).every(q=>(p.school+' '+p.search).toLowerCase().includes(q))));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/18)));const visible=computed(()=>filtered.value.slice((page.value-1)*18,page.value*18));const picked=computed(()=>selected.value.map(id=>all.value.find(p=>p.id===id)).filter(Boolean));
function toggle(id){note.value='';if(selected.value.includes(id)){selected.value=selected.value.filter(x=>x!==id)}else if(selected.value.length<4){selected.value=[...selected.value,id]}else note.value='最多同时比较 4 个条目，请先移除一个。'}
async function compare(){showCompare.value=true;await nextTick();compareEl.value?.scrollIntoView({behavior:'smooth'});compareEl.value?.focus();}
async function share(){const u=new URL(location.href);u.search='';u.searchParams.set('compare',selected.value.join(','));try{await navigator.clipboard.writeText(u.toString());note.value='已复制对比链接。'}catch{note.value='浏览器不支持复制，请复制地址栏中的链接。';history.replaceState(null,'',u.toString());}}
const rows=[['basic','基本信息'],['admission','招生与申请要求'],['courses','课程与先修'],['fees','费用、资助与去向'],['fit','金融数学适配性'],['dates','申请日期']];
function reset(){query.value='';region.value='';school.value='';tag.value='';}
</script>
<template><div class="app-page explorer"><header class="page-intro"><div class="eyebrow">FIND YOUR PROGRAM</div><h1>让项目之间的差异，清晰可见。</h1><p>搜索课程、考试科目或职业方向；选取最多 4 个条目，比较培养方向、申请要求与费用。</p></header><div class="filter-bar"><label class="search-field"><span>⌕</span><input v-model="query" placeholder="搜索：金融工程、Python、431、GRE…" aria-label="搜索项目全文"></label><label class="select-field"><span>地区</span><select v-model="region"><option value="">全部地区</option><option v-for="(n,id) in catalog.regions" :value="id">{{n}}</option></select></label><label class="select-field"><span>大学</span><select v-model="school"><option value="">全部大学</option><option v-for="s in schools" :value="s.id">{{s.name}}</option></select></label></div><div class="chips"><button :class="{active:!tag}" @click="tag=''">全部方向</button><button v-for="c in categories" :class="{active:tag===c}" @click="tag=c">{{c}}</button></div><p class="helper">按兴趣筛选方向，也可以输入课程名称、考试科目或学校名称。</p><div class="result-summary"><span role="status">{{loading?'正在加载项目资料…':`找到 ${filtered.length} 个项目 / 培养方向条目`}}</span><button v-if="query||region||school||tag" @click="reset" class="text-button">重置筛选</button><a :href="withBase('/data/programs.csv')" download>下载完整索引 CSV ↓</a></div><div v-if="error" class="empty-state" role="alert">{{error}} <button class="button secondary" @click="load">重试</button></div><div class="program-grid"><article v-for="p in visible" :key="p.id" class="program-card" :class="{selected:selected.includes(p.id)}"><div class="school-card-top"><span>{{p.school}}</span><span class="region-mini">{{p.regionName}}</span></div><a :href="withBase(p.url)"><h2>{{p.title}}</h2></a><p class="program-dept">{{p.department}}</p><p class="program-degree">{{p.degree}}</p><p class="program-focus">{{p.focus}}</p><div class="program-meta">参考 {{p.years?.join(' / ')}} · 核验 {{p.verified}}</div><div class="school-links"><a :href="withBase(p.url)">查看项目详情 ↗</a><button @click="toggle(p.id)" :aria-pressed="selected.includes(p.id)">{{selected.includes(p.id)?'✓ 已加入对比':'+ 加入对比'}}</button></div></article></div><div v-if="!loading&&!error&&!filtered.length" class="empty-state"><h2>没有找到匹配条目</h2><p>试试放宽地区或方向，或输入更短的关键词。</p><button class="button secondary" @click="reset">清除筛选</button></div><nav v-if="!loading&&filtered.length" class="pagination" aria-label="项目分页"><button :disabled="page===1" @click="page--">← 上一页</button><span>{{page}} / {{pages}}</span><button :disabled="page===pages" @click="page++">下一页 →</button></nav>
<div v-if="selected.length" class="compare-tray"><div><strong>已选 {{selected.length}} / 4</strong><div class="selected-tags"><button v-for="p in picked" @click="toggle(p.id)" :aria-label="'移除 '+p.school+' '+p.title">{{p.school}} · {{p.title.slice(0,12)}} ×</button></div></div><div class="tray-actions"><button class="text-button" @click="selected=[];showCompare=false">清空</button><button class="button primary" @click="compare">开始对比 →</button></div></div><p v-if="note" role="status" class="feedback">{{note}}</p>
<section v-if="showCompare&&picked.length" ref="compareEl" tabindex="-1" class="comparison"><div class="section-heading"><div><div class="eyebrow">SIDE BY SIDE</div><h2>跨校项目对比</h2></div><div><button class="text-button" @click="share">复制对比链接</button><button class="text-button" @click="showCompare=false">收起</button></div></div><p class="notice-text">请留意费用的币种和计费周期。不同培养方向可能共用招生名额，不能重复求和；参考旧年度的信息不代表 2028 年要求。</p><div class="comparison-scroll" role="region" aria-label="跨校对比表，可横向滚动" tabindex="0"><table><thead><tr><th scope="col">比较维度</th><th v-for="p in picked" scope="col"><span>{{p.school}}</span><a :href="withBase(p.url)">{{p.title}} ↗</a><small>参考 {{p.years?.join(' / ')}}<br>资料日期 {{p.verified}}</small></th></tr></thead><tbody><tr v-for="[key,label] in rows"><th scope="row">{{label}}</th><td v-for="p in picked"><div class="comparison-text" v-html="p.fields[key]"></div></td></tr></tbody></table></div></section>
</div></template>
